/**
 * Deck archetypes — the "template library" surface the user picks from.
 *
 * An archetype is a named narrative shape: a pure function that maps one content
 * outline (`CarouselContent`) into a full `CarouselProps` deck by arranging the
 * existing slide kinds (cover / statement / list / takeaway) in a particular
 * order. Adding a template = adding an archetype here; no engine change, because
 * the slide kinds it composes already exist.
 *
 * This is the layer above slide kinds: users never pick "a cover slide", they
 * pick "a Listicle" and the archetype decides which kinds to emit. The same
 * `build()` an LLM brief tool will call to emit a deck from a user's prompt.
 */

import type {
  CarouselImageAsset,
  CarouselProps,
  CarouselSlide,
  CarouselVisualRequest,
  CarouselVisualStyle,
} from "./types";

export interface CarouselContent {
  /** The hook / cover line. */
  hook: string;
  /** Substring of the hook to italicise in ink-blue (the editorial accent). */
  accent?: string;
  /** Optional cover subtitle. */
  subtitle?: string;
  /** Title for the rundown slide in the Listicle archetype. */
  listTitle?: string;
  /** Body beats. Each becomes a list item or its own statement slide. */
  points: string[];
  /** Closing payoff line (the takeaway title). */
  payoff: string;
  /** Closing call-to-action behind the red bar. */
  cta?: string;
  /** Value-first bridge into the product proof. */
  bridge?: string;
  /** Concrete evidence used immediately before the product reveal. */
  productProof?: string;
  /** Product-led closing line. Falls back to payoff. */
  productReveal?: string;
  /** Optional commercial disclosure shown on the final slide. */
  disclosure?: string;
  /** Ordered, rights-cleared images. One image is assigned to each slide. */
  images?: CarouselImageAsset[];
  /** Ordered image-layer requests. They never contain final slide typography. */
  visualRequests?: CarouselVisualRequest[];
  /** Brand handle in the footer. */
  handle?: string;
}

export interface CarouselArchetype {
  id: string;
  label: string;
  /** One line on the narrative shape — the "why this template" affordance. */
  blurb: string;
  /** Pure: content → deck. Same content, different structure per archetype. */
  build: (content: CarouselContent) => CarouselProps;
}

function frame(
  slides: CarouselSlide[],
  content: CarouselContent,
  visualStyle: CarouselVisualStyle = "editorial"
): CarouselProps {
  return {
    slides: slides.map((slide, index) => ({
      ...slide,
      image: content.images?.[index],
      visualRequest: content.visualRequests?.[index],
    })),
    handle: content.handle,
    showPageNumber: true,
    visualStyle,
  };
}

/**
 * Hook → numbered rundown → payoff. The classic social carousel. Best when the
 * points are parallel items the reader scans as a set.
 */
const listicle: CarouselArchetype = {
  id: "listicle",
  label: "Listicle",
  blurb: "Hook, a numbered rundown on one slide, then the payoff.",
  build: (c) =>
    frame(
      [
        {
          kind: "cover",
          title: c.hook,
          accent: c.accent,
          subtitle: c.subtitle,
        },
        {
          kind: "list",
          title: c.listTitle ?? "The rundown",
          items: c.points,
        },
        { kind: "takeaway", title: c.payoff, accent: c.accent, cta: c.cta },
      ],
      c
    ),
};

/**
 * Hook → one idea per slide → payoff. Best for a persuasive build where each
 * beat earns its own beat of attention.
 */
const manifesto: CarouselArchetype = {
  id: "manifesto",
  label: "Manifesto",
  blurb: "Hook, then one punchy idea per slide, building to the payoff.",
  build: (c) =>
    frame(
      [
        {
          kind: "cover",
          title: c.hook,
          accent: c.accent,
          subtitle: c.subtitle,
        },
        ...c.points.map(
          (p): CarouselSlide => ({
            kind: "statement",
            statement: p,
          })
        ),
        { kind: "takeaway", title: c.payoff, cta: c.cta },
      ],
      c
    ),
};

/**
 * Hook → the problem → the contrast → payoff. Best when you're reframing a
 * status quo: state how it is, then how it could be.
 */
const beforeAfter: CarouselArchetype = {
  id: "before-after",
  label: "Before / After",
  blurb: "Hook, the problem, the contrast, then the payoff.",
  build: (c) => {
    const problem = c.points[0] ?? "";
    const contrast = c.points[c.points.length - 1] ?? problem;
    return frame(
      [
        {
          kind: "cover",
          title: c.hook,
          accent: c.accent,
          subtitle: c.subtitle,
        },
        { kind: "statement", statement: problem, footnote: "The status quo" },
        { kind: "statement", statement: contrast, footnote: "The shift" },
        { kind: "takeaway", title: c.payoff, accent: c.accent, cta: c.cta },
      ],
      c
    );
  },
};

/**
 * Give away the useful answer first, then earn a restrained product reveal.
 * The structure is fixed at six slides so variants remain comparable:
 * hook, three value beats, bridge plus proof, product reveal plus CTA.
 */
const valueFirstReveal: CarouselArchetype = {
  id: "value-first-reveal",
  label: "Value-First Reveal",
  blurb:
    "Three useful beats first, then proof and a restrained product reveal.",
  build: (c) => {
    const beats = [0, 1, 2].map(
      (index) => c.points[index] ?? c.points.at(-1) ?? c.payoff
    );
    const bridge = c.bridge ?? "Here is what makes this repeatable.";
    const proof = c.productProof ?? c.payoff;
    return frame(
      [
        {
          kind: "cover",
          title: c.hook,
          accent: c.accent,
          subtitle: c.subtitle,
        },
        { kind: "statement", statement: beats[0]!, footnote: "01 · The value" },
        { kind: "statement", statement: beats[1]!, footnote: "02 · The value" },
        { kind: "statement", statement: beats[2]!, footnote: "03 · The value" },
        {
          kind: "statement",
          statement: bridge,
          footnote: `Proof · ${proof}`,
        },
        {
          kind: "takeaway",
          title: c.productReveal ?? c.payoff,
          cta: [c.cta, c.disclosure].filter(Boolean).join(" · ") || undefined,
        },
      ],
      c
    );
  },
};

export const CAROUSEL_ARCHETYPES: CarouselArchetype[] = [
  listicle,
  manifesto,
  beforeAfter,
  valueFirstReveal,
];

export function getArchetype(id: string): CarouselArchetype | undefined {
  return CAROUSEL_ARCHETYPES.find((a) => a.id === id);
}

/**
 * Default-and-show: pick the best-fit archetype so the user always lands on a
 * rendered deck, with the others offered as one-tap swaps.
 *
 * v1 heuristic is deliberately simple — the real picker is the LLM, which will
 * choose from the prompt's intent. This just guarantees a sensible default:
 *   2 points        → Before / After (a natural two-sided contrast)
 *   5+ points       → Listicle (too many for one-idea-per-slide)
 *   otherwise (1-4) → Manifesto (room to let each beat breathe)
 */
export function pickDefaultArchetype(content: CarouselContent): string {
  const n = content.points.length;
  if (n === 2) return beforeAfter.id;
  if (n >= 5) return listicle.id;
  return manifesto.id;
}

